SELECT count(*),avg(completed_at-started) FROM runs WHERE /*account:character:runs.character_id*/=/*account:run:?3*/ AND dungeon=?1 AND outcome='cleared' AND started<?2 AND completed_at>started AND CASE WHEN json_valid(json) THEN json_extract(json,'$.area_kind') END='dungeon' AND EXISTS(SELECT 1 FROM run_evidence e WHERE e.run_id=runs.id AND e.kind IN ('victory','completion_dialogue'))
